content.query:
let UserUPN = tostring('{UPN}');
let InternalDomain = tostring(split(UserUPN,'@')[1]);
// --------------------------
// Normalize helper values
// --------------------------
let NowTs = now();

// --------------------------
// 1) Identity: Interactive sign-ins (summary-ish)
// --------------------------
let T_Signins =
SigninLogs
| extend UPNNorm = tostring(column_ifexists('UserPrincipalName', column_ifexists('Identity','')))
| where UPNNorm == UserUPN
| where tobool(column_ifexists('IsInteractive', true)) == true
| extend IPNorm = tostring(column_ifexists('IPAddress', column_ifexists('IpAddress','')))
| extend LocationNorm = tostring(column_ifexists('Location', ''))
| extend AppNorm = tostring(column_ifexists('AppDisplayName',''))
| extend ResultTypeNorm = toint(column_ifexists('ResultType', 0))
| extend CAStatusNorm = tostring(column_ifexists('ConditionalAccessStatus',''))
| extend RiskStateNorm = tostring(column_ifexists('RiskState','none'))
| extend RiskLevelAggNorm = tostring(column_ifexists('RiskLevelAggregated',''))
| extend Action = iif(ResultTypeNorm == 0, 'Interactive Sign-in (Success)', 'Interactive Sign-in (Failure)')
| extend Details = strcat('App=', AppNorm, '; CA=', CAStatusNorm, '; RiskState=', RiskStateNorm, '; RiskLevel=', RiskLevelAggNorm, '; ResultType=', tostring(ResultTypeNorm))
| extend SeverityScore = case(
    ResultTypeNorm != 0, 70,
    RiskLevelAggNorm =~ 'high', 80,
    RiskLevelAggNorm =~ 'medium', 65,
    RiskStateNorm != 'none', 60,
    CAStatusNorm has_any ('failure','Failure'), 60,
    25
)
| project TimeGenerated, Source='SigninLogs', Category='Identity', Action, Details, IPAddress=IPNorm, DeviceName=tostring(column_ifexists('DeviceDetail','')), Workload='', Item='', SiteUrl='', Recipient='', SeverityScore;

// --------------------------
// 2) Identity: Risky/failed sign-ins (event-level emphasis)
// --------------------------
let T_RiskyAuth =
SigninLogs
| extend UPNNorm = tostring(column_ifexists('UserPrincipalName', column_ifexists('Identity','')))
| where UPNNorm == UserUPN
| extend ResultTypeNorm = toint(column_ifexists('ResultType', 0))
| extend RiskStateNorm  = tostring(column_ifexists('RiskState', 'none'))
| extend RiskLevelAggNorm = tostring(column_ifexists('RiskLevelAggregated', ''))
| extend CAStatusNorm   = tostring(column_ifexists('ConditionalAccessStatus', ''))
| where ResultTypeNorm != 0 or RiskStateNorm != 'none' or CAStatusNorm has_any ('failure','Failure')
| extend IPNorm = tostring(column_ifexists('IPAddress', column_ifexists('IpAddress','')))
| extend LocationNorm = tostring(column_ifexists('Location',''))
| extend AppNorm = tostring(column_ifexists('AppDisplayName',''))
| extend Action = 'Risky/Failed Sign-in'
| extend Details = strcat('App=', AppNorm, '; Location=', LocationNorm, '; CA=', CAStatusNorm, '; RiskState=', RiskStateNorm, '; RiskLevel=', RiskLevelAggNorm, '; ResultType=', tostring(ResultTypeNorm))
| extend SeverityScore = case(
    RiskLevelAggNorm =~ 'high', 100,
    RiskLevelAggNorm =~ 'medium', 85,
    RiskLevelAggNorm =~ 'low', 70,
    ResultTypeNorm != 0, 75,
    CAStatusNorm has_any ('failure','Failure'), 70,
    60
)
| project TimeGenerated, Source='SigninLogs', Category='Identity', Action, Details, IPAddress=IPNorm, DeviceName=tostring(column_ifexists('DeviceDetail','')), Workload='', Item='', SiteUrl='', Recipient='', SeverityScore;

// --------------------------
// 3) O365: SharePoint/OneDrive downloads (OfficeActivity)
// --------------------------
let T_SPODownloads =
OfficeActivity
| where UserId == UserUPN
| extend WorkloadNorm = tostring(column_ifexists('OfficeWorkload', column_ifexists('Workload','')))
| where WorkloadNorm in ('SharePoint','OneDrive')
| where Operation in ('FileDownloaded','FileSyncDownloadedFull','FileSyncDownloadedPartial')
| extend SiteUrlNorm  = tostring(column_ifexists('Site_Url', column_ifexists('SiteUrl','')))
| extend ClientIPNorm = tostring(column_ifexists('ClientIP', column_ifexists('ClientIp','')))
| extend ItemNorm = tostring(column_ifexists('SourceFileName',''))
| extend Action = strcat(WorkloadNorm, ' Download')
| extend Details = strcat('Op=', Operation)
| extend SeverityScore = 55
| project TimeGenerated, Source='OfficeActivity', Category='Cloud Files', Action, Details, IPAddress=ClientIPNorm, DeviceName='', Workload=WorkloadNorm, Item=ItemNorm, SiteUrl=SiteUrlNorm, Recipient='', SeverityScore;

// --------------------------
// 4) Email: External recipients (EmailEvents)
// --------------------------
let T_ExternalEmail =
EmailEvents
| where SenderFromAddress == UserUPN
| extend RecipientNorm = tostring(column_ifexists('RecipientEmailAddress',''))
| extend RecipientDomain = tostring(split(RecipientNorm,'@')[1])
| where isnotempty(RecipientDomain) and RecipientDomain !~ InternalDomain
| extend Action = 'Email Sent (External Recipient)'
| extend Details = strcat('To=', RecipientNorm, '; Domain=', RecipientDomain, '; Subject=', tostring(column_ifexists('Subject','')))
| extend IPNorm = tostring(column_ifexists('SenderIPv4',''))
| extend SeverityScore = 40
| project TimeGenerated, Source='EmailEvents', Category='Email', Action, Details, IPAddress=IPNorm, DeviceName='', Workload='', Item='', SiteUrl='', Recipient=RecipientNorm, SeverityScore;

// --------------------------
// 5) Email: External emails with attachments (EmailAttachmentInfo + EmailEvents)
// --------------------------
let T_ExternalEmailAttach =
EmailAttachmentInfo
| join kind=inner (
    EmailEvents
    | where SenderFromAddress == UserUPN
    | extend RecipientNorm = tostring(column_ifexists('RecipientEmailAddress',''))
    | extend RecipientDomain = tostring(split(RecipientNorm,'@')[1])
) on NetworkMessageId
| where isnotempty(RecipientDomain) and RecipientDomain !~ InternalDomain
| extend FileNorm = tostring(column_ifexists('FileName',''))
| extend Action = 'Email Sent (External Attachment)'
| extend Details = strcat('To=', RecipientNorm, '; File=', FileNorm, '; Subject=', tostring(column_ifexists('Subject','')))
| extend IPNorm = tostring(column_ifexists('SenderIPv4',''))
| extend SeverityScore = case(
    FileNorm has_any ('.zip','.7z','.rar'), 85,
    FileNorm has_any ('.pst','.mbox'), 90,
    70
)
| project TimeGenerated, Source='EmailAttachmentInfo', Category='Email', Action, Details, IPAddress=IPNorm, DeviceName='', Workload='', Item=FileNorm, SiteUrl='', Recipient=RecipientNorm, SeverityScore;

// --------------------------
// 6) Endpoint: Local file staging (DeviceFileEvents)
// --------------------------
let T_LocalStaging =
DeviceFileEvents
| where InitiatingProcessAccountUpn == UserUPN
| where ActionType == 'FileCreated'
| where FolderPath has_any ('\\Downloads\\','\\Desktop\\','\\Documents\\')
| extend DeviceNorm = tostring(column_ifexists('DeviceName',''))
| extend FileNorm = tostring(column_ifexists('FileName',''))
| extend ProcNorm = tostring(column_ifexists('InitiatingProcessFileName',''))
| extend Action = 'Local File Created (Staging Path)'
| extend Details = strcat('File=', FileNorm, '; Path=', tostring(column_ifexists('FolderPath','')), '; Proc=', ProcNorm)
| extend SeverityScore = case(
    FileNorm has_any ('.zip','.7z','.rar'), 70,
    FileNorm has_any ('.csv','.xlsx'), 60,
    45
)
| project TimeGenerated, Source='DeviceFileEvents', Category='Endpoint', Action, Details, IPAddress='', DeviceName=DeviceNorm, Workload='', Item=FileNorm, SiteUrl='', Recipient='', SeverityScore;

// --------------------------
// 7) Endpoint: USB events (DeviceEvents)
// --------------------------
let T_USB =
DeviceEvents
| where InitiatingProcessAccountUpn == UserUPN
| where ActionType in ('UsbDriveMounted','UsbDriveFileCopied')
| extend DeviceNorm = tostring(column_ifexists('DeviceName',''))
| extend Action = case(ActionType == 'UsbDriveFileCopied', 'USB File Copied', 'USB Drive Mounted')
| extend Details = tostring(column_ifexists('AdditionalFields',''))
| extend SeverityScore = case(ActionType == 'UsbDriveFileCopied', 90, 35)
| project TimeGenerated, Source='DeviceEvents', Category='Removable Media', Action, Details, IPAddress='', DeviceName=DeviceNorm, Workload='', Item='', SiteUrl='', Recipient='', SeverityScore;

// --------------------------
// 8) CAS: Cloud App events (CloudAppEvents)
// --------------------------
let T_CAS =
CloudAppEvents
| extend UPNNorm = tostring(column_ifexists('UserPrincipalName', column_ifexists('UserId', column_ifexists('AccountId',''))))
| where UPNNorm == UserUPN
| extend AppNameNorm = tostring(column_ifexists('AppName', column_ifexists('Application','')))
| extend ActionTypeNorm = tostring(column_ifexists('ActionType', column_ifexists('ActivityType','')))
| extend IPNorm = tostring(column_ifexists('IPAddress', column_ifexists('IpAddress', column_ifexists('ClientIP',''))))
| extend DeviceTypeNorm = tostring(column_ifexists('DeviceType', column_ifexists('Device','')))
| extend UserAgentNorm = tostring(column_ifexists('UserAgent', column_ifexists('UserAgentString','')))
| extend Action = 'Cloud App Activity'
| extend Details = strcat('App=', AppNameNorm, '; Action=', ActionTypeNorm, '; DeviceType=', DeviceTypeNorm, '; UA=', UserAgentNorm)
| extend SeverityScore = 35
| project TimeGenerated, Source='CloudAppEvents', Category='Cloud Apps', Action, Details, IPAddress=IPNorm, DeviceName='', Workload='', Item='', SiteUrl='', Recipient='', SeverityScore;

// --------------------------
// Unified timeline output
// --------------------------
union isfuzzy=true T_RiskyAuth, T_USB, T_ExternalEmailAttach, T_SPODownloads, T_LocalStaging, T_ExternalEmail, T_CAS, T_Signins
| extend TimeBucket = bin(TimeGenerated, 5m)
| project TimeGenerated, TimeBucket, Category, Source, SeverityScore, Action, Details, IPAddress, DeviceName, Workload, SiteUrl, Item, Recipient
| order by TimeGenerated desc
